# Create sentiment analysis API service
sentiment_analysis_service = '''#!/usr/bin/env python3
"""
🎯 HUGGING FACE SENTIMENT ANALYSIS API
Mobile-optimized sentiment analysis service for business intelligence
"""

import os
import json
import time
from datetime import datetime
from flask import Flask, request, jsonify
from transformers import pipeline, AutoTokenizer, AutoModelForSequenceClassification
import logging
import re

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class SentimentAnalysisService:
    def __init__(self):
        self.app = Flask(__name__)
        # Using lightweight model optimized for mobile
        self.model_name = "cardiffnlp/twitter-roberta-base-sentiment-latest"
        self.classifier = None
        self.usage_stats = {
            "requests": 0, 
            "texts_analyzed": 0,
            "sentiment_distribution": {"positive": 0, "negative": 0, "neutral": 0}
        }

        self.setup_routes()
        self.load_model()

    def load_model(self):
        """Load lightweight sentiment analysis model"""
        try:
            logger.info(f"Loading sentiment model: {self.model_name}")

            # Load model with pipeline for efficiency
            self.classifier = pipeline(
                "sentiment-analysis",
                model=self.model_name,
                device=-1,  # CPU only for mobile
                return_all_scores=True
            )

            logger.info("✅ Sentiment model loaded successfully!")

        except Exception as e:
            logger.error(f"❌ Error loading sentiment model: {str(e)}")
            # Fallback to a smaller model if the main one fails
            try:
                logger.info("Trying fallback model...")
                self.classifier = pipeline(
                    "sentiment-analysis",
                    model="distilbert-base-uncased-finetuned-sst-2-english",
                    device=-1,
                    return_all_scores=True
                )
                logger.info("✅ Fallback sentiment model loaded!")
            except Exception as fallback_error:
                logger.error(f"❌ Fallback model failed: {str(fallback_error)}")
                raise

    def preprocess_text(self, text):
        """Clean and preprocess text for better sentiment analysis"""
        if not text or not isinstance(text, str):
            return ""

        # Remove extra whitespace
        text = re.sub(r'\s+', ' ', text.strip())

        # Handle special characters and emojis (keep them as they contain sentiment)
        # Just ensure text isn't too long
        if len(text) > 512:
            text = text[:512]

        return text

    def interpret_sentiment(self, scores):
        """Convert model scores to business-friendly sentiment labels"""
        if not scores:
            return {"sentiment": "neutral", "confidence": 0.0}

        # Find highest scoring sentiment
        best_score = max(scores, key=lambda x: x['score'])
        sentiment_label = best_score['label'].lower()
        confidence = best_score['score']

        # Normalize labels to consistent format
        label_mapping = {
            'positive': 'positive',
            'negative': 'negative', 
            'neutral': 'neutral',
            'label_2': 'positive',  # Some models use numeric labels
            'label_1': 'neutral',
            'label_0': 'negative'
        }

        normalized_sentiment = label_mapping.get(sentiment_label, 'neutral')

        return {
            "sentiment": normalized_sentiment,
            "confidence": round(confidence, 4),
            "all_scores": scores
        }

    def setup_routes(self):
        """Setup API routes"""

        @self.app.route('/health', methods=['GET'])
        def health_check():
            return jsonify({
                'status': 'healthy',
                'model': self.model_name,
                'service': 'sentiment-analysis',
                'timestamp': datetime.now().isoformat()
            })

        @self.app.route('/analyze', methods=['POST'])
        def analyze_sentiment():
            try:
                data = request.get_json()

                if not data or 'text' not in data:
                    return jsonify({'error': 'Missing text in request'}), 400

                text = data['text']

                if not text or len(text.strip()) == 0:
                    return jsonify({'error': 'Empty text provided'}), 400

                # Preprocess text
                clean_text = self.preprocess_text(text)

                if len(clean_text) == 0:
                    return jsonify({'error': 'Text too short or invalid'}), 400

                start_time = time.time()

                # Perform sentiment analysis
                scores = self.classifier(clean_text)

                analysis_time = time.time() - start_time

                # Interpret results
                result = self.interpret_sentiment(scores[0] if scores else [])

                # Update statistics
                self.usage_stats['requests'] += 1
                self.usage_stats['texts_analyzed'] += 1
                self.usage_stats['sentiment_distribution'][result['sentiment']] += 1

                return jsonify({
                    'text': text[:100] + "..." if len(text) > 100 else text,
                    'sentiment': result['sentiment'],
                    'confidence': result['confidence'],
                    'analysis_time': round(analysis_time, 3),
                    'model': self.model_name,
                    'timestamp': datetime.now().isoformat()
                })

            except Exception as e:
                logger.error(f"Sentiment analysis error: {str(e)}")
                return jsonify({'error': str(e)}), 500

        @self.app.route('/batch-analyze', methods=['POST'])
        def batch_analyze():
            """Analyze multiple texts at once"""
            try:
                data = request.get_json()

                if not data or 'texts' not in data:
                    return jsonify({'error': 'Missing texts array in request'}), 400

                texts = data['texts']

                if not isinstance(texts, list) or len(texts) == 0:
                    return jsonify({'error': 'texts must be a non-empty array'}), 400

                if len(texts) > 50:  # Limit batch size for mobile
                    return jsonify({'error': 'Maximum 50 texts per batch'}), 400

                start_time = time.time()
                results = []

                for i, text in enumerate(texts):
                    if not text or not isinstance(text, str):
                        results.append({
                            'index': i,
                            'text': str(text)[:50] + "..." if len(str(text)) > 50 else str(text),
                            'error': 'Invalid text'
                        })
                        continue

                    clean_text = self.preprocess_text(text)

                    if len(clean_text) == 0:
                        results.append({
                            'index': i,
                            'text': text[:50] + "..." if len(text) > 50 else text,
                            'error': 'Text too short or invalid'
                        })
                        continue

                    try:
                        scores = self.classifier(clean_text)
                        result = self.interpret_sentiment(scores[0] if scores else [])

                        results.append({
                            'index': i,
                            'text': text[:50] + "..." if len(text) > 50 else text,
                            'sentiment': result['sentiment'],
                            'confidence': result['confidence']
                        })

                        # Update stats
                        self.usage_stats['texts_analyzed'] += 1
                        self.usage_stats['sentiment_distribution'][result['sentiment']] += 1

                    except Exception as text_error:
                        results.append({
                            'index': i,
                            'text': text[:50] + "..." if len(text) > 50 else text,
                            'error': str(text_error)
                        })

                total_time = time.time() - start_time
                self.usage_stats['requests'] += 1

                return jsonify({
                    'results': results,
                    'total_texts': len(texts),
                    'successful_analyses': len([r for r in results if 'sentiment' in r]),
                    'total_time': round(total_time, 3),
                    'model': self.model_name,
                    'timestamp': datetime.now().isoformat()
                })

            except Exception as e:
                logger.error(f"Batch analysis error: {str(e)}")
                return jsonify({'error': str(e)}), 500

        @self.app.route('/business-insights', methods=['POST'])
        def business_insights():
            """Analyze customer feedback or reviews for business insights"""
            try:
                data = request.get_json()
                feedbacks = data.get('feedbacks', [])

                if not feedbacks:
                    return jsonify({'error': 'No feedbacks provided'}), 400

                insights = {
                    'total_feedback': len(feedbacks),
                    'sentiment_summary': {'positive': 0, 'negative': 0, 'neutral': 0},
                    'confidence_stats': {'high': 0, 'medium': 0, 'low': 0},
                    'sample_feedback': {'positive': [], 'negative': [], 'neutral': []},
                    'overall_score': 0.0
                }

                positive_scores = []

                for feedback in feedbacks[:20]:  # Limit for mobile processing
                    if isinstance(feedback, str) and feedback.strip():
                        clean_text = self.preprocess_text(feedback)
                        scores = self.classifier(clean_text)
                        result = self.interpret_sentiment(scores[0] if scores else [])

                        sentiment = result['sentiment']
                        confidence = result['confidence']

                        # Update summary
                        insights['sentiment_summary'][sentiment] += 1

                        # Confidence categories
                        if confidence > 0.8:
                            insights['confidence_stats']['high'] += 1
                        elif confidence > 0.6:
                            insights['confidence_stats']['medium'] += 1
                        else:
                            insights['confidence_stats']['low'] += 1

                        # Sample feedback (first few of each sentiment)
                        if len(insights['sample_feedback'][sentiment]) < 2:
                            insights['sample_feedback'][sentiment].append({
                                'text': feedback[:100] + "..." if len(feedback) > 100 else feedback,
                                'confidence': confidence
                            })

                        # Calculate overall business score
                        if sentiment == 'positive':
                            positive_scores.append(confidence)
                        elif sentiment == 'negative':
                            positive_scores.append(-confidence)
                        else:
                            positive_scores.append(0)

                # Calculate overall business sentiment score (-1 to 1)
                if positive_scores:
                    insights['overall_score'] = round(sum(positive_scores) / len(positive_scores), 3)

                return jsonify({
                    'business_insights': insights,
                    'recommendations': self.generate_recommendations(insights),
                    'timestamp': datetime.now().isoformat()
                })

            except Exception as e:
                return jsonify({'error': str(e)}), 500

        @self.app.route('/stats', methods=['GET'])
        def get_stats():
            """Get usage statistics"""
            return jsonify({
                'usage_stats': self.usage_stats,
                'model_info': {
                    'name': self.model_name,
                    'type': 'sentiment-analysis'
                },
                'timestamp': datetime.now().isoformat()
            })

    def generate_recommendations(self, insights):
        """Generate business recommendations based on sentiment analysis"""
        recommendations = []

        total = insights['total_feedback']
        positive_pct = (insights['sentiment_summary']['positive'] / total * 100) if total > 0 else 0
        negative_pct = (insights['sentiment_summary']['negative'] / total * 100) if total > 0 else 0

        if positive_pct > 70:
            recommendations.append("🎉 Strong positive sentiment! Leverage this for marketing.")
        elif positive_pct > 50:
            recommendations.append("👍 Generally positive. Focus on maintaining quality.")
        elif negative_pct > 50:
            recommendations.append("⚠️ High negative sentiment. Immediate attention needed.")

        if insights['confidence_stats']['low'] > insights['confidence_stats']['high']:
            recommendations.append("🔍 Many unclear sentiments. Consider more targeted feedback collection.")

        return recommendations

    def run(self, host='0.0.0.0', port=8002, debug=False):
        """Run the Flask service"""
        logger.info(f"🚀 Starting Sentiment Analysis Service on {host}:{port}")
        self.app.run(host=host, port=port, debug=debug)

if __name__ == '__main__':
    service = SentimentAnalysisService()
    service.run()
'''

